// ============================================
// NORMALIZE DATA SINGLE - FIXED FOR SUPABASE DIRECT OUTPUT
// Handles direct output from Supabase Vector Store
// ============================================

const items = $input.all();
function getNodeJson(names) {
  for (const name of names) {
    try {
      const data = $(name).first().json;
      if (data) return data;
    } catch (e) {}
  }
  return {};
}
const plannerContext = getNodeJson(["Parse Intent Classifier Output", "Parse Rewritten Query1", "Session Manager1"]);


console.log('=== NORMALIZE DATA SINGLE (FIXED) ===');
console.log('📥 Input items:', items.length);

if (items.length === 0) {
  console.log('❌ No input items!');
  return [{
    json: {
      ...plannerContext,
      error: "No input items",
      context: "Tidak ada data dari Single Path Retriever.",
      total_chunks: 0
    }
  }];
}

const normalized = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;

  console.log(`\n--- Processing item ${i + 1} ---`);
  console.log('📋 Keys:', Object.keys(data));

  // CASE 1: Direct Supabase output with "document" field
  if (data.document) {
    console.log('✅ Found direct Supabase output format');

    const doc = data.document;
    const content = doc.pageContent || doc.content || "";
    const metadata = doc.metadata || {};
    const similarity = data.score || 0.7;

    // VALIDATE: Must have content and doc_id
    const hasContent = content && content.length >= 50;
    const hasDocId = metadata.doc_id && 
                     metadata.doc_id !== "" && 
                     metadata.doc_id !== "Dokumen Tidak Diketahui";

    if (!hasContent) {
      console.log(`⚠️ Skipping: Content too short (${content.length} chars)`);
      continue;
    }

    if (!hasDocId) {
      console.log('⚠️ Skipping: Missing or invalid doc_id');
      continue;
    }

    normalized.push({
      json: {
        content: content,
        metadata: {
          doc_id: metadata.doc_id,
          chunk_id: metadata.chunk_id,
          chunk_type: metadata.chunk_type || "content",
          page_start: metadata.page_start || null,
          page_end: metadata.page_end || null,
          language: metadata.language || "id",
          ...metadata  // Preserve all other fields
        },
        similarity: similarity
      }
    });

    console.log(`✅ Extracted: ${content.substring(0, 80)}...`);
    console.log(`   Doc ID: ${metadata.doc_id}`);
    console.log(`   Pages: ${metadata.page_start || 'N/A'}-${metadata.page_end || 'N/A'}`);
    console.log(`   Similarity: ${similarity.toFixed(3)}`);
    continue;
  }

  // CASE 2: Direct document format (pageContent/content at root)
  if (data.pageContent || data.content) {
    console.log('✅ Found direct document format');

    const content = data.pageContent || data.content || "";
    const metadata = data.metadata || {};
    const similarity = data.similarity || data.score || 0.7;

    const hasContent = content && content.length >= 50;
    const hasDocId = metadata.doc_id && 
                     metadata.doc_id !== "" && 
                     metadata.doc_id !== "Dokumen Tidak Diketahui";

    if (!hasContent || !hasDocId) {
      console.log('⚠️ Skipping: Invalid content or doc_id');
      continue;
    }

    normalized.push({
      json: {
        content: content,
        metadata: {
          doc_id: metadata.doc_id,
          chunk_id: metadata.chunk_id,
          chunk_type: metadata.chunk_type || "content",
          page_start: metadata.page_start || null,
          page_end: metadata.page_end || null,
          language: metadata.language || "id",
          ...metadata
        },
        similarity: similarity
      }
    });

    console.log(`✅ Extracted: ${content.substring(0, 80)}...`);
    continue;
  }

  // CASE 3: Nested in output field (fallback for Agent output)
  let rawOutput = data.output || data.tool_results || null;

  if (rawOutput) {
    console.log('📦 Found output/tool_results field');

    // Parse if stringified
    if (typeof rawOutput === 'string') {
      try {
        rawOutput = JSON.parse(rawOutput);
        console.log('✅ Parsed stringified output');
      } catch (e) {
        console.log('❌ Failed to parse:', e.message);
        continue;
      }
    }

    // Extract documents from various nested structures
    let documents = [];

    if (Array.isArray(rawOutput)) {
      documents = rawOutput;
    } else if (rawOutput.document) {
      documents = [rawOutput.document];
    } else if (rawOutput.pageContent || rawOutput.content) {
      documents = [rawOutput];
    }

    // Process each document
    for (const doc of documents) {
      const content = doc.pageContent || doc.content || "";
      const metadata = doc.metadata || {};
      const similarity = doc.similarity || doc.score || 0.7;

      const hasContent = content && content.length >= 50;
      const hasDocId = metadata.doc_id && 
                       metadata.doc_id !== "" && 
                       metadata.doc_id !== "Dokumen Tidak Diketahui";

      if (!hasContent || !hasDocId) {
        continue;
      }

      normalized.push({
        json: {
          content: content,
          metadata: {
            doc_id: metadata.doc_id,
            chunk_id: metadata.chunk_id,
            chunk_type: metadata.chunk_type || "content",
            page_start: metadata.page_start || null,
            page_end: metadata.page_end || null,
            language: metadata.language || "id",
            ...metadata
          },
          similarity: similarity
        }
      });
    }
  }
}

console.log(`\n=== NORMALIZE COMPLETE ===`);
console.log(`📤 Output items: ${normalized.length}`);

if (normalized.length === 0) {
  console.log('❌ WARNING: No valid documents extracted!');
  console.log('💡 Check input data structure');

  return [{
    json: {
      ...plannerContext,
      error: "No valid documents",
      context: "Gagal extract dokumen. Periksa struktur data input.",
      total_chunks: 0,
      debug: {
        input_items: items.length,
        sample_structure: items[0] ? Object.keys(items[0].json) : []
      }
    }
  }];
}

// Log sample of normalized data
if (normalized.length > 0) {
  console.log('\n📊 Sample normalized item:');
  console.log('  Content length:', normalized[0].json.content.length);
  console.log('  Doc ID:', normalized[0].json.metadata.doc_id);
  console.log('  Similarity:', normalized[0].json.similarity);
}

return normalized;

// ============================================
// ANSWER-TYPE HYBRID RERANKER - EXPLICIT EXAMPLE RECALL
// Single-path reranker with example/exception/boundary boost.
// ============================================

const chunks = $input.all();

console.log("=== ANSWER-TYPE HYBRID RERANKER - EXAMPLE RECALL ===");
console.log("Input chunks:", chunks.length);

let planner = {};
try {
  planner = $("Parse Intent Classifier Output3").first().json || {};
} catch (e) {
  console.log("Could not get planner:", e.message);
}

const currentQuery =
  planner.rewritten_query ||
  planner.optimized_query ||
  planner.original_query ||
  "Pertanyaan tidak tersedia";

const keywords = Array.isArray(planner.keywords) ? planner.keywords : [];
const answerType = planner.answer_type || "definition";
const intent = planner.intent || "general";
const mustFind = Array.isArray(planner.must_find) ? planner.must_find : [];
const targetConcept = planner.target_concept || "";
const evidenceTypes = Array.isArray(planner.evidence_type) ? planner.evidence_type : [];

console.log("Intent:", intent);
console.log("Answer type:", answerType);
console.log("Evidence types:", evidenceTypes);
console.log("Target concept:", targetConcept);
console.log("Keywords:", keywords);
console.log("Must find:", mustFind);

if (chunks.length === 0) {
  return [{
    json: {
      ...planner,
      chunks: [],
      total_chunks: 0,
      strategy: "single_path",
      current_query: currentQuery,
      answer_type: answerType
    }
  }];
}

function safeLower(value) {
  return String(value || "").toLowerCase();
}

function countSignals(text, signals) {
  return signals.filter(signal => text.includes(signal)).length;
}

function uniqueArray(arr) {
  return [...new Set(arr.filter(Boolean))];
}

const signalMap = {
  definition: [
    "adalah", "yang dimaksud", "dimaksud", "definisi", "konsep",
    "merupakan", "meliputi", "terdiri dari", "disebut", "mencakup"
  ],
  criteria: [
    "jika", "apabila", "syarat", "kriteria", "ketentuan", "maka",
    "termasuk", "dikategorikan", "dicatat", "minimal", "paling sedikit"
  ],
  duration: [
    "tahun", "bulan", "hari", "minimal", "paling sedikit", "kurang dari",
    "lebih dari", "selama", "bermaksud", "berniat", "menetap", "tinggal"
  ],
  classification: [
    "jika", "apabila", "maka", "termasuk", "dikategorikan", "dicatat",
    "status", "kategori", "klasifikasi", "syarat", "kriteria"
  ],
  code: [
    "kode", "rincian", "variabel", "isian", "kategori", "pilihan",
    "mig_", "kbli", "kbji", "1", "2", "3", "4"
  ],
  procedure: [
    "cara", "langkah", "prosedur", "isi", "isikan", "ditanyakan",
    "lanjut", "skip", "alur", "pengisian"
  ],
  example: [
    "contoh", "misalnya", "ilustrasi", "kasus", "seperti"
  ],
  comparison: [
    "berbeda", "perbedaan", "dibandingkan", "sedangkan", "sementara",
    "tetapi", "namun"
  ]
};

function getSignalsForAnswerType(type) {
  return signalMap[type] || [];
}

const exampleSignals = [
  "contoh",
  "sebagai contoh",
  "misalnya",
  "ilustrasi",
  "kasus",
  "contoh kasus",
  "contoh berikut",
  "seperti"
];

const operationalExampleSignals = [
  "dianggap bekerja",
  "dianggap tidak bekerja",
  "digolongkan bekerja",
  "tidak digolongkan bekerja",
  "tidak digolongkan sebagai bekerja",
  "dikategorikan bekerja",
  "tidak dikategorikan bekerja",
  "tidak dikategorikan sebagai bekerja",
  "dicatat sebagai bekerja",
  "tidak dicatat sebagai bekerja",
  "dapat dikategorikan bekerja",
  "tidak termasuk bekerja",
  "termasuk bekerja"
];

const exceptionSignals = [
  "pengecualian",
  "batasan",
  "namun",
  "tetapi",
  "kecuali",
  "tidak menghasilkan barang atau jasa",
  "menghasilkan barang atau jasa",
  "disetarakan dengan pengemis",
  "tidak digolongkan sebagai bekerja",
  "tidak dikategorikan sebagai bekerja",
  "tidak digolongkan bekerja",
  "tidak dikategorikan bekerja",
  "bukan bekerja",
  "tidak bekerja"
];

const boundarySignals = [
  "manusia silver",
  "pak ogah",
  "pengemis",
  "meminta-minta",
  "meminta uang",
  "lampu merah",
  "atraksi",
  "patung hidup",
  "pantomim",
  "kemampuan akting",
  "ketahanan fisik",
  "aktivitas jalanan"
];

const answerSignals = getSignalsForAnswerType(answerType);

const queryTerms = safeLower(`${currentQuery} ${targetConcept} ${mustFind.join(" ")} ${keywords.join(" ")} ${evidenceTypes.join(" ")}`)
  .split(/\s+/)
  .filter(t => t.length >= 4);

const needsException =
  evidenceTypes.includes("exception_rule") ||
  evidenceTypes.includes("boundary_case") ||
  safeLower(targetConcept).includes("batasan") ||
  safeLower(targetConcept).includes("exception") ||
  safeLower(currentQuery).includes("manusia silver") ||
  safeLower(currentQuery).includes("pengemis") ||
  safeLower(currentQuery).includes("meminta-minta") ||
  safeLower(currentQuery).includes("pak ogah");

const isCaseQuestion =
  answerType === "classification" ||
  answerType === "criteria" ||
  needsException;

const rerankedChunks = chunks.map((item, idx) => {
  const data = item.json || {};
  const content = data.content || "";
  const metadata = data.metadata || {};
  const semanticScore = Number(data.similarity || data.score || 0.7);
  const contentLower = safeLower(content);

  const keywordMatches = keywords.filter(kw => contentLower.includes(safeLower(kw)));
  const keywordScore = keywords.length > 0 ? keywordMatches.length / keywords.length : 0;

  const answerSignalCount = countSignals(contentLower, answerSignals);
  let answerTypeBoost = 0;
  if (answerSignalCount >= 1) answerTypeBoost += 0.08;
  if (answerSignalCount >= 2) answerTypeBoost += 0.08;
  if (answerSignalCount >= 3) answerTypeBoost += 0.06;

  const mustFindHits = mustFind.filter(m => contentLower.includes(safeLower(m)));
  let mustFindBoost = 0;
  if (mustFindHits.length >= 1) mustFindBoost += 0.10;
  if (mustFindHits.length >= 2) mustFindBoost += 0.12;
  if (mustFindHits.length >= 3) mustFindBoost += 0.08;

  const queryTermHits = uniqueArray(queryTerms).filter(t => contentLower.includes(t));
  const lexicalCoverage = queryTerms.length ? Math.min(queryTermHits.length / Math.min(queryTerms.length, 12), 1) : 0;

  const exampleHitCount = countSignals(contentLower, exampleSignals);
  const operationalHitCount = countSignals(contentLower, operationalExampleSignals);
  const exceptionHitCount = countSignals(contentLower, exceptionSignals);
  const boundaryHitCount = countSignals(contentLower, boundarySignals);

  let exampleBoost = 0;
  let exceptionBoost = 0;
  let boundaryBoost = 0;

  if (isCaseQuestion) {
    if (exampleHitCount >= 1) exampleBoost += 0.08;
    if (exampleHitCount >= 2) exampleBoost += 0.08;

    if (operationalHitCount >= 1) exampleBoost += 0.12;
    if (operationalHitCount >= 2) exampleBoost += 0.10;

    if (exceptionHitCount >= 1) exceptionBoost += 0.12;
    if (exceptionHitCount >= 2) exceptionBoost += 0.14;
    if (exceptionHitCount >= 3) exceptionBoost += 0.10;

    if (boundaryHitCount >= 1) boundaryBoost += 0.10;
    if (boundaryHitCount >= 2) boundaryBoost += 0.12;
    if (boundaryHitCount >= 3) boundaryBoost += 0.10;
  }

  if (needsException) {
    if (exceptionHitCount === 0 && boundaryHitCount === 0) {
      exceptionBoost -= 0.08;
    }
    if (exceptionHitCount >= 1 && boundaryHitCount >= 1) {
      exceptionBoost += 0.12;
    }
  }

  let metadataBoost = 0;
  const chunkType = safeLower(metadata.chunk_type || "");
  if (answerType === "definition" && (chunkType.includes("konsep") || chunkType.includes("definisi"))) metadataBoost += 0.06;
  if (answerType === "code" && (chunkType.includes("kode") || chunkType.includes("form") || chunkType.includes("rincian"))) metadataBoost += 0.08;
  if (answerType === "procedure" && (chunkType.includes("pedoman") || chunkType.includes("form"))) metadataBoost += 0.06;
  if (isCaseQuestion && (chunkType.includes("contoh") || chunkType.includes("kasus") || chunkType.includes("example"))) metadataBoost += 0.12;

  const pageStart = Number(metadata.page_start || 999);
  const positionPenalty = Math.min(pageStart / 500, 0.02);

  const hybridScore =
    (semanticScore * 0.42) +
    (keywordScore * 0.15) +
    (lexicalCoverage * 0.10) +
    answerTypeBoost +
    mustFindBoost +
    exampleBoost +
    exceptionBoost +
    boundaryBoost +
    metadataBoost -
    positionPenalty;

  return {
    content,
    metadata,
    similarity: semanticScore,
    keyword_score: keywordScore,
    keyword_matches: keywordMatches,
    lexical_coverage: lexicalCoverage,
    query_term_hits: queryTermHits,
    answer_type_boost: answerTypeBoost,
    answer_signal_count: answerSignalCount,
    must_find_boost: mustFindBoost,
    must_find_hits: mustFindHits,
    example_boost: exampleBoost,
    exception_boost: exceptionBoost,
    boundary_boost: boundaryBoost,
    example_hit_count: exampleHitCount,
    operational_hit_count: operationalHitCount,
    exception_hit_count: exceptionHitCount,
    boundary_hit_count: boundaryHitCount,
    metadata_boost: metadataBoost,
    needs_exception: needsException,
    hybrid_score: hybridScore
  };
});

rerankedChunks.sort((a, b) => b.hybrid_score - a.hybrid_score);
const topChunks = rerankedChunks.slice(0, 6);

console.log("Top chunks:", topChunks.map((c, i) => ({
  rank: i + 1,
  score: Number(c.hybrid_score.toFixed(3)),
  example_boost: c.example_boost,
  exception_boost: c.exception_boost,
  boundary_boost: c.boundary_boost,
  must_find_boost: c.must_find_boost,
  lexical_coverage: Number(c.lexical_coverage.toFixed(2)),
  doc_id: c.metadata.doc_id,
  page_start: c.metadata.page_start
})));

return [{
  json: {
    ...planner,
    chunks: topChunks,
    total_chunks: topChunks.length,
    strategy: "single_path",
    rerank_method: "answer_type_hybrid_example_recall",
    current_query: currentQuery,
    answer_type: answerType,
    evidence_type: evidenceTypes
  }
}];

const analyzer = $input.first().json || {};
const subqueries = Array.isArray(analyzer.subqueries) ? analyzer.subqueries : [];

console.log("Splitting into", subqueries.length, "paths");
console.log("Answer type:", analyzer.answer_type);
console.log("Target concept:", analyzer.target_concept);

if (subqueries.length === 0) {
  return [{
    json: {
      ...analyzer,
      path_number: 1,
      focus: "fallback",
      query: analyzer.optimized_query || analyzer.rewritten_query || analyzer.original_query || "",
      top_k: 6,
      weight: 1.0
    }
  }];
}

return subqueries.map((sq, idx) => ({
  json: {
    ...analyzer,
    path_number: sq.path || idx + 1,
    focus: sq.focus || "query",
    query: sq.query || analyzer.rewritten_query || analyzer.original_query || "",
    top_k: sq.top_k || 6,
    weight: sq.weight || 1.0,
    original_query: analyzer.original_query || "",
    rewritten_query: analyzer.rewritten_query || analyzer.optimized_query || analyzer.original_query || "",
    keywords: analyzer.keywords || [],
    answer_type: analyzer.answer_type || "definition",
    target_concept: analyzer.target_concept || "",
    must_find: analyzer.must_find || [],
    session_key: analyzer.session_key,
    session_bucket: analyzer.session_bucket,
    payload: analyzer.payload || {}
  }
}));

/**
 * NORMALIZE DATA MULTI - FIXED FOR DIRECT SUPABASE OUTPUT
 * Handles the actual structure from Supabase Vector Store
 */

const items = $input.all();

console.log('=== NORMALIZE DATA MULTI (FIXED v2) ===');
console.log('📥 Total items:', items.length);

if (items.length === 0) {
  console.log('⚠️ No items to normalize!');
  return [];
}

// --- Get Path Info SAFELY ---
let pathInfo = { path_number: 1, focus: 'unknown', weight: 1.0 };
try {
  pathInfo = $('Loop Paths3').first().json;
  console.log(`🔀 Path: ${pathInfo.path_number} | Focus: ${pathInfo.focus}`);
} catch (e) {
  console.log('⚠️ Could not get Loop Paths info, using defaults');
}

// --- Process Each Item ---
const normalized = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;

  console.log(`\n--- Processing item ${i + 1} ---`);
  console.log('📋 Keys:', Object.keys(data));

  // CASE 1: Direct Supabase output with "document" field
  if (data.document) {
    console.log('✅ Found direct Supabase output format');

    const doc = data.document;
    const content = doc.pageContent || doc.content || "";
    const metadata = doc.metadata || {};
    const similarity = data.score || 0.7;

    // VALIDATE: Must have content and doc_id
    const hasContent = content && content.length >= 50;
    const hasDocId = metadata.doc_id && 
                     metadata.doc_id !== "" && 
                     metadata.doc_id !== "Dokumen Tidak Diketahui";

    if (!hasContent) {
      console.log(`⚠️ Skipping: Content too short (${content.length} chars)`);
      continue;
    }

    if (!hasDocId) {
      console.log('⚠️ Skipping: Missing or invalid doc_id');
      continue;
    }

    normalized.push({
      json: {
        ...pathInfo,
        content: content,
        metadata: {
          doc_id: metadata.doc_id,
          chunk_id: metadata.chunk_id,
          chunk_type: metadata.chunk_type || "content",
          page_start: metadata.page_start || null,
          page_end: metadata.page_end || null,
          language: metadata.language || "id",
          ...metadata  // Preserve all other fields
        },
        similarity: similarity,
        path_number: pathInfo.path_number,
        focus: pathInfo.focus,
        weight: pathInfo.weight
      }
    });

    console.log(`✅ Extracted: ${content.substring(0, 80)}...`);
    console.log(`   Doc ID: ${metadata.doc_id}`);
    console.log(`   Pages: ${metadata.page_start || 'N/A'}-${metadata.page_end || 'N/A'}`);
    console.log(`   Similarity: ${similarity.toFixed(3)}`);
    continue;
  }

  // CASE 2: Direct document format (pageContent/content at root)
  if (data.pageContent || data.content) {
    console.log('✅ Found direct document format');

    const content = data.pageContent || data.content || "";
    const metadata = data.metadata || {};
    const similarity = data.similarity || data.score || 0.7;

    const hasContent = content && content.length >= 50;
    const hasDocId = metadata.doc_id && 
                     metadata.doc_id !== "" && 
                     metadata.doc_id !== "Dokumen Tidak Diketahui";

    if (!hasContent || !hasDocId) {
      console.log('⚠️ Skipping: Invalid content or doc_id');
      continue;
    }

    normalized.push({
      json: {
        ...pathInfo,
        content: content,
        metadata: {
          doc_id: metadata.doc_id,
          chunk_id: metadata.chunk_id,
          chunk_type: metadata.chunk_type || "content",
          page_start: metadata.page_start || null,
          page_end: metadata.page_end || null,
          language: metadata.language || "id",
          ...metadata
        },
        similarity: similarity,
        path_number: pathInfo.path_number,
        focus: pathInfo.focus,
        weight: pathInfo.weight
      }
    });

    console.log(`✅ Extracted: ${content.substring(0, 80)}...`);
    continue;
  }

  console.log('⚠️ Item structure not recognized, skipping');
}

// --- Logging Summary ---
console.log(`\n=== NORMALIZATION COMPLETE ===`);
console.log(`📤 Total extracted: ${normalized.length} docs`);

if (normalized.length === 0) {
  console.log('❌ ERROR: No documents extracted. Check input structure.');
  console.log('🔍 Sample input structure:');
  if (items.length > 0) {
    console.log(JSON.stringify(items[0].json, null, 2).substring(0, 500));
  }
} else {
  // Log first doc metadata
  console.log('📊 First doc metadata:', {
    doc_id: normalized[0].json.metadata.doc_id,
    page_start: normalized[0].json.metadata.page_start,
    page_end: normalized[0].json.metadata.page_end,
    path: normalized[0].json.path_number,
    focus: normalized[0].json.focus
  });
}

return normalized;

// ============================================
// ANSWER-TYPE CROSS-PATH RERANKER - EXPLICIT EXAMPLE + MULTI-DEFINITION RECALL
// Multi-path merger + example/exception/boundary-aware reranking.
// Optimized for:
// - boundary / exception cases
// - explicit operational examples
// - multi-definition queries with different concepts across paths
// ============================================

const allResults = $input.all();
const uniqueChunks = new Map();

let planner = {};
try {
  planner = $("Parse Intent Classifier Output3").first().json || {};
} catch (e) {
  console.log("Could not get planner:", e.message);
}

const keywords = Array.isArray(planner.keywords) ? planner.keywords : [];
const answerType = planner.answer_type || "classification";
const mustFind = Array.isArray(planner.must_find) ? planner.must_find : [];
const currentQuery = planner.rewritten_query || planner.original_query || "Pertanyaan tidak tersedia";
const targetConcept = planner.target_concept || "";
const evidenceTypes = Array.isArray(planner.evidence_type) ? planner.evidence_type : [];
const strategy = planner.strategy || "multi_path";

console.log("=== ANSWER-TYPE CROSS-PATH RERANKER - EXAMPLE + MULTI-DEFINITION RECALL ===");
console.log("Items:", allResults.length);
console.log("Answer type:", answerType);
