      evidence_type: evidenceTypes
    }
  }];
}

// ---------- Helpers ----------
function safeLower(value) {
  return String(value || "").toLowerCase();
}

function countSignals(text, signals) {
  return signals.filter(signal => text.includes(signal)).length;
}

function uniqueArray(arr) {
  return [...new Set(arr.filter(Boolean))];
}

function normalizeKey(content, metadata) {
  const chunkId = metadata?.chunk_id || "";
  const docId = metadata?.doc_id || "";
  const pageStart = metadata?.page_start || "";
  const pageEnd = metadata?.page_end || "";

  if (chunkId) return `chunk_id:${chunkId}`;
  if (docId && pageStart) return `doc:${docId}|page:${pageStart}-${pageEnd}|text:${content.slice(0, 80).toLowerCase()}`;

  return content.trim().toLowerCase();
}

// ---------- Signal Maps ----------
const signalMap = {
