// ---------- Query/Case Detection ----------
const answerSignals = signalMap[answerType] || [];

const combinedPlannerText = safeLower(
  `${currentQuery} ${targetConcept} ${mustFind.join(" ")} ${keywords.join(" ")} ${evidenceTypes.join(" ")}`
);

const queryTerms = combinedPlannerText
  .split(/\s+/)
  .filter(t => t.length >= 4);

const needsException =
  evidenceTypes.includes("exception_rule") ||
  evidenceTypes.includes("boundary_case") ||
  safeLower(targetConcept).includes("batasan") ||
  combinedPlannerText.includes("manusia silver") ||
  combinedPlannerText.includes("pengemis") ||
  combinedPlannerText.includes("meminta-minta") ||
  combinedPlannerText.includes("pak ogah");

const isCaseQuestion =
  answerType === "classification" ||
  answerType === "criteria" ||
  needsException;

const isMultiDefinition =
  answerType === "definition" &&
  (
    mustFind.length >= 3 ||
    keywords.filter(k => multiDefinitionConcepts.includes(safeLower(k))).length >= 2 ||
    combinedPlannerText.includes("definisi operasional") ||
    combinedPlannerText.includes("konsep ketenagakerjaan") ||
    combinedPlannerText.includes("angkatan kerja") && combinedPlannerText.includes("bukan angkatan kerja") ||
    combinedPlannerText.includes("bekerja") && combinedPlannerText.includes("pengangguran")
  );

console.log("Needs exception:", needsException);
console.log("Is case question:", isCaseQuestion);
console.log("Is multi-definition:", isMultiDefinition);

// ---------- Merge Duplicate Chunks ----------
for (const item of allResults) {
  const data = item.json || {};
  const pathNumber = data.path_number || 1;
  const weight = Number(data.weight || 1.0);
  const focus = data.focus || "unknown";
  const content = data.content || "";
  const metadata = data.metadata || {};
  const similarity = Number(data.similarity || 0.7);

  if (!content || content.trim().length < 50) continue;

  const key = normalizeKey(content, metadata);

  if (!uniqueChunks.has(key)) {
    uniqueChunks.set(key, {
      content,
      metadata,
      paths: [{ path: pathNumber, focus, weight }],
      max_similarity: similarity,
      weighted_scores: [similarity * weight]
    });
  } else {
    const existing = uniqueChunks.get(key);
    existing.paths.push({ path: pathNumber, focus, weight });
    existing.max_similarity = Math.max(existing.max_similarity, similarity);
    existing.weighted_scores.push(similarity * weight);
  }
}

// ---------- Score Chunks ----------
const mergedChunks = Array.from(uniqueChunks.values()).map(chunk => {
  const content = chunk.content || "";
  const contentLower = safeLower(content);
  const metadata = chunk.metadata || {};

  const pathCount = chunk.paths.length;
  const avgWeightedSimilarity =
    chunk.weighted_scores.reduce((a, b) => a + b, 0) / chunk.weighted_scores.length;

  const keywordMatches = keywords.filter(kw => contentLower.includes(safeLower(kw)));
  const keywordScore = keywords.length > 0 ? keywordMatches.length / keywords.length : 0;

  const focusSet = new Set(chunk.paths.map(p => safeLower(p.focus)));
  const focusList = [...focusSet];

  let crossPathBoost = 0;
  let diversityScore = 0;

  if (isMultiDefinition) {
    // Untuk multi-definition, chunk berbeda konsep tidak harus muncul di banyak path.
    // Jadi cross-path boost jangan terlalu dominan.
    crossPathBoost = Math.min((pathCount - 1) * 0.04, 0.10);
    diversityScore = Math.min(focusSet.size * 0.03, 0.10);
  } else {
    crossPathBoost = Math.min((pathCount - 1) * 0.10, 0.30);
    diversityScore = Math.min(focusSet.size * 0.04, 0.16);
  }

  const hasExceptionPath = chunk.paths.some(p => safeLower(p.focus).includes("exception"));
  const hasCriteriaPath = chunk.paths.some(p => safeLower(p.focus).includes("criteria"));
  const hasConceptPath = chunk.paths.some(p => safeLower(p.focus).includes("concept"));

  let pathFocusBoost = 0;
  if (hasExceptionPath) pathFocusBoost += 0.10;
  if (hasCriteriaPath) pathFocusBoost += 0.04;
  if (hasConceptPath && !isMultiDefinition) pathFocusBoost += 0.02;

  const answerSignalCount = countSignals(contentLower, answerSignals);
  let answerTypeBoost = 0;
  if (answerSignalCount >= 1) answerTypeBoost += 0.08;
  if (answerSignalCount >= 2) answerTypeBoost += 0.08;
  if (answerSignalCount >= 3) answerTypeBoost += 0.06;

  const mustFindHits = mustFind.filter(m => contentLower.includes(safeLower(m)));
  let mustFindBoost = 0;
  if (mustFindHits.length >= 1) mustFindBoost += 0.10;
  if (mustFindHits.length >= 2) mustFindBoost += 0.12;
  if (mustFindHits.length >= 3) mustFindBoost += 0.08;

  const queryTermHits = uniqueArray(queryTerms).filter(t => contentLower.includes(t));
  const lexicalCoverage = queryTerms.length
    ? Math.min(queryTermHits.length / Math.min(queryTerms.length, 12), 1)
    : 0;

  const exampleHitCount = countSignals(contentLower, exampleSignals);
  const operationalHitCount = countSignals(contentLower, operationalExampleSignals);
  const exceptionHitCount = countSignals(contentLower, exceptionSignals);
  const boundaryHitCount = countSignals(contentLower, boundarySignals);

  let exampleBoost = 0;
  let exceptionBoost = 0;
  let boundaryBoost = 0;

  if (isCaseQuestion) {
    if (exampleHitCount >= 1) exampleBoost += 0.08;
    if (exampleHitCount >= 2) exampleBoost += 0.08;

    if (operationalHitCount >= 1) exampleBoost += 0.12;
    if (operationalHitCount >= 2) exampleBoost += 0.10;

    if (exceptionHitCount >= 1) exceptionBoost += 0.12;
    if (exceptionHitCount >= 2) exceptionBoost += 0.14;
    if (exceptionHitCount >= 3) exceptionBoost += 0.10;

    if (boundaryHitCount >= 1) boundaryBoost += 0.10;
    if (boundaryHitCount >= 2) boundaryBoost += 0.12;
    if (boundaryHitCount >= 3) boundaryBoost += 0.10;
  }

  if (needsException) {
    if (exceptionHitCount === 0 && boundaryHitCount === 0) {
      exceptionBoost -= 0.08;
    }
    if (exceptionHitCount >= 1 && boundaryHitCount >= 1) {
      exceptionBoost += 0.12;
    }
  }

  // Multi-definition concept coverage
  const conceptHits = multiDefinitionConcepts.filter(c => contentLower.includes(c));
  const focusConceptHits = focusList.filter(f => multiDefinitionConcepts.includes(f));

  let multiDefinitionBoost = 0;

  if (isMultiDefinition) {
    if (answerSignalCount >= 1) multiDefinitionBoost += 0.08;
    if (conceptHits.length >= 1) multiDefinitionBoost += 0.10;
    if (mustFindHits.length >= 1) multiDefinitionBoost += 0.12;
    if (focusConceptHits.length >= 1) multiDefinitionBoost += 0.12;

    // Jangan terlalu menghukum chunk yang hanya menjawab satu konsep,
    // karena memang tujuan multi-definition adalah mengambil chunk berbeda per konsep.
    if (focusConceptHits.length === 1 || conceptHits.length === 1) {
      multiDefinitionBoost += 0.08;
    }
  }

  const chunkType = safeLower(metadata.chunk_type || "");
  let metadataBoost = 0;

  if (isCaseQuestion && (chunkType.includes("contoh") || chunkType.includes("kasus") || chunkType.includes("example"))) {
    metadataBoost += 0.12;
  }

  if (isMultiDefinition && (chunkType.includes("konsep") || chunkType.includes("definisi") || chunkType.includes("content"))) {
    metadataBoost += 0.06;
  }

  let finalScore;

  if (isMultiDefinition) {
    // Formula khusus multi-definition:
    // lexical/mustFind/focus coverage lebih penting daripada cross-path agreement.
    finalScore =
      (avgWeightedSimilarity * 0.36) +
      (keywordScore * 0.12) +
      (lexicalCoverage * 0.14) +
      answerTypeBoost +
      mustFindBoost +
      multiDefinitionBoost +
      metadataBoost +
      crossPathBoost +
      diversityScore;
  } else {
    // Formula normal untuk classification/boundary/general multi-path.
    finalScore =
      (avgWeightedSimilarity * 0.38) +
      (keywordScore * 0.14) +
      (lexicalCoverage * 0.10) +
      crossPathBoost +
      diversityScore +
      pathFocusBoost +
      answerTypeBoost +
      mustFindBoost +
      exampleBoost +
      exceptionBoost +
      boundaryBoost +
      metadataBoost;
  }

  return {
    content,
    metadata,
    similarity: chunk.max_similarity,
    path_count: pathCount,
    paths: chunk.paths,
    cross_path_boost: crossPathBoost,
    path_focus_boost: pathFocusBoost,
    keyword_score: keywordScore,
    keyword_matches: keywordMatches,
    lexical_coverage: lexicalCoverage,
    query_term_hits: queryTermHits,
    diversity_score: diversityScore,
    answer_type_boost: answerTypeBoost,
    answer_signal_count: answerSignalCount,
    must_find_boost: mustFindBoost,
    must_find_hits: mustFindHits,
    example_boost: exampleBoost,
    exception_boost: exceptionBoost,
    boundary_boost: boundaryBoost,
    example_hit_count: exampleHitCount,
    operational_hit_count: operationalHitCount,
    exception_hit_count: exceptionHitCount,
    boundary_hit_count: boundaryHitCount,
    multi_definition_boost: multiDefinitionBoost,
    concept_hits: conceptHits,
    focus_concept_hits: focusConceptHits,
    metadata_boost: metadataBoost,
    needs_exception: needsException,
    is_multi_definition: isMultiDefinition,
    final_score: finalScore
  };
});

// ---------- Sort ----------
mergedChunks.sort((a, b) => b.final_score - a.final_score);

// ---------- Coverage-aware Selection ----------
let topChunks = [];

if (isMultiDefinition) {
  const desiredConcepts = uniqueArray([
    ...keywords.filter(k => multiDefinitionConcepts.includes(safeLower(k))).map(safeLower),
    ...mustFind
      .map(m => safeLower(m))
      .flatMap(m => multiDefinitionConcepts.filter(c => m.includes(c))),
    ...multiDefinitionConcepts.filter(c => combinedPlannerText.includes(c))
  ]);

  console.log("Desired concepts:", desiredConcepts);

  const selectedKeys = new Set();

  // 1) Ambil best chunk per requested concept
  for (const concept of desiredConcepts) {
    const candidate = mergedChunks.find(chunk => {
      const contentLower = safeLower(chunk.content);
      const focusMatch = chunk.focus_concept_hits.includes(concept);
      const contentMatch = contentLower.includes(concept);
      return focusMatch || contentMatch;
    });

    if (candidate) {
      const key = normalizeKey(candidate.content, candidate.metadata);
      if (!selectedKeys.has(key)) {
        topChunks.push(candidate);
        selectedKeys.add(key);
      }
    }
  }

  // 2) Lengkapi dengan skor tertinggi
  for (const chunk of mergedChunks) {
    if (topChunks.length >= 10) break;

    const key = normalizeKey(chunk.content, chunk.metadata);
    if (!selectedKeys.has(key)) {
      topChunks.push(chunk);
      selectedKeys.add(key);
    }
  }
} else {
  topChunks = mergedChunks.slice(0, 8);
}

console.log("Top chunks:", topChunks.map((c, i) => ({
  rank: i + 1,
  score: Number(c.final_score.toFixed(3)),
  path_count: c.path_count,
  is_multi_definition: c.is_multi_definition,
  concept_hits: c.concept_hits,
  focus_concept_hits: c.focus_concept_hits,
  example_boost: c.example_boost,
  exception_boost: c.exception_boost,
  boundary_boost: c.boundary_boost,
  multi_definition_boost: c.multi_definition_boost,
  must_find_boost: c.must_find_boost,
  doc_id: c.metadata.doc_id,
  page_start: c.metadata.page_start
})));

return [{
  json: {
    ...planner,
    chunks: topChunks,
    total_chunks: topChunks.length,
    strategy: "multi_path",
    multi_path_count: topChunks.filter(c => c.path_count > 1).length,
    rerank_method: isMultiDefinition
      ? "answer_type_cross_path_multi_definition_recall"
      : "answer_type_cross_path_example_recall",
    current_query: currentQuery,
    answer_type: answerType,
    evidence_type: evidenceTypes,
    is_multi_definition: isMultiDefinition
  }
}];

