function normalizePageValue(value) {
  if (value === undefined || value === null || value === "") return null;
  return value;
}

function buildPageRef(pageStart, pageEnd) {
  if (pageStart && pageEnd && pageStart !== pageEnd) return `Hal. ${pageStart}-${pageEnd}`;
  if (pageStart) return `Hal. ${pageStart}`;
  if (pageEnd) return `Hal. ${pageEnd}`;
  return "Hal. N/A";
}

function truncateText(text, maxLength = 1200) {
  const value = String(text || "");
  if (value.length <= maxLength) return value;
  return value.slice(0, maxLength) + "\n...[dipotong untuk efisiensi konteks]";
}

function getNodeJson(names) {
  for (const name of names) {
    try {
      const data = $(name).first().json;
      if (data) return data;
    } catch (e) {
      // try next
    }
  }
  return {};
}

