const from = payload.from || result.payload?.from || planner.payload?.from || rewritten.payload?.from || sessionManager.payload?.from || "";
const sessionBucket = result.session_bucket || planner.session_bucket || rewritten.session_bucket || sessionManager.session_bucket || "";
const computedSessionKey = from && sessionBucket ? `${from}_${sessionBucket}` : "";
const sessionKey = result.session_key || planner.session_key || rewritten.session_key || sessionManager.session_key || computedSessionKey || "default_session";

const originalQuery = result.original_query || planner.original_query || result.payload?.body || "";
const rewrittenQuery = result.rewritten_query || planner.rewritten_query || result.current_query || originalQuery;
