      keyword_score: chunk.keyword_score || null,
      hybrid_score: chunk.hybrid_score || null,
      final_score: chunk.final_score || null,
      answer_type_boost: chunk.answer_type_boost || 0,
      must_find_boost: chunk.must_find_boost || 0,
      example_boost: chunk.example_boost || 0,
