      boundary_hit_count: chunk.boundary_hit_count || 0,
      lexical_coverage: chunk.lexical_coverage || 0,
      path_count: chunk.path_count || null
    }
  };
});

const sources = validChunks.map((chunk, idx) => {
  const metadata = chunk.metadata || {};
  const pageStart = normalizePageValue(metadata.page_start || metadata.page_end);
  const pageEnd = normalizePageValue(metadata.page_end || metadata.page_start);

  return {
    id: idx + 1,
    doc_id: metadata.doc_id,
    page_ref: buildPageRef(pageStart, pageEnd),
    chunk_type: metadata.chunk_type || "content"
  };
});

const contextJson = {
