function levenshtein(a, b) {
  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[b.length][a.length];
}

function isCloseToGreeting(text) {
  const greetingWords = [
    "halo", "hallo", "helo", "hello", "hai", "hi", "hey", "hei",
    "pagi", "siang", "sore", "malam", "assalamualaikum", "salam"
  ];

  if (text.length < 3 || text.length > 12) return false;

  return greetingWords.some(word => levenshtein(text, word) <= 1);
}

function isShortNonsense(text) {
  if (text.length < 3 || text.length > 6) return false;
  if (/\d/.test(text)) return false;

  const allowedShortTerms = [
    "kbli", "kbji", "tpt", "krt", "art", "pkl",
    "ojol", "ojek", "padi", "kos"
  ];

  if (allowedShortTerms.includes(text)) return false;

  return /^[a-z]+$/i.test(text) && !text.includes(" ");
}

const greetingPatterns = [
  /^(halo|hallo|helo|hai|hello|hi|hey|hei|hoy|woy)$/i,
  /^(halo|hallo|helo|hai|hello|hi|hey|hei|hoy|woy)\s*[!.?]+$/i,

  /^p$/i,
