// ============================================
// ANSWER-TYPE RERANKER RETRY
// Same general scoring philosophy as the main reranker,
// but uses retry_query and annotates retry metadata.
// ============================================

const chunks = $input.all();

let planner = {};
try {
  planner = $("Parse Intent Classifier Output3").first().json || {};
} catch (e) {
  console.log("Could not get planner:", e.message);
}

let retryData = {};
try {
  retryData = $("Build Retry Retrieval Query1").first().json || {};
} catch (e) {
  console.log("Could not get retry data:", e.message);
}

const currentQuery =
  retryData.retry_query ||
  planner.rewritten_query ||
  planner.optimized_query ||
  planner.original_query ||
  "Pertanyaan tidak tersedia";

const keywords = Array.isArray(planner.keywords) ? planner.keywords : [];
const answerType = planner.answer_type || retryData.answer_type || "definition";
const intent = planner.intent || "general";
const mustFind = Array.isArray(planner.must_find) ? planner.must_find : [];
const targetConcept = planner.target_concept || "";

function safeLower(value) {
  return String(value || "").toLowerCase();
}

function countSignals(text, signals) {
  return signals.filter(signal => text.includes(safeLower(signal))).length;
}

function tokenize(text) {
  return safeLower(text)
    .replace(/[^\p{L}\p{N}_]+/gu, " ")
    .split(/\s+/)
    .filter(t => t.length >= 3);
}

const answerTypeSignals = {
  definition: ["adalah", "yang dimaksud", "merupakan", "definisi", "konsep", "cakupan", "meliputi", "terdiri dari"],
  criteria: ["jika", "apabila", "maka", "kriteria", "syarat", "ketentuan", "termasuk", "dicatat"],
  duration: ["tahun", "bulan", "hari", "minimal", "paling sedikit", "kurang dari", "lebih dari", "selama", "bermaksud", "berniat"],
  classification: ["jika", "apabila", "maka", "termasuk", "dikategorikan", "dicatat", "status", "kategori"],
  code: ["kode", "rincian", "variabel", "isian", "kategori", "mig_", "kbli", "kbji"],
  procedure: ["cara", "langkah", "prosedur", "isi", "isikan", "ditanyakan", "lanjut", "skip"],
  example: ["contoh", "misalnya", "kasus", "seperti"],
  comparison: ["berbeda", "perbedaan", "dibandingkan", "sedangkan", "sementara"]
};

const queryTerms = tokenize(`${currentQuery} ${targetConcept} ${mustFind.join(" ")} ${keywords.join(" ")}`);
const signals = answerTypeSignals[answerType] || [];

if (chunks.length === 0) {
  return [{
    json: {
      ...planner,
      ...retryData,
      chunks: [],
      total_chunks: 0,
      strategy: "retry_path",
      rerank_method: "answer_type_retry",
      current_query: currentQuery,
      answer_type: answerType
    }
  }];
}

const rerankedChunks = chunks.map((item, idx) => {
  const data = item.json || {};
  const content = data.content || "";
  const metadata = data.metadata || {};
  const contentLower = safeLower(content);
  const semanticScore = Number(data.similarity || data.score || 0.7);

  const keywordMatches = keywords.filter(kw => contentLower.includes(safeLower(kw)));
  const keywordScore = keywords.length ? keywordMatches.length / keywords.length : 0;

  const answerSignalCount = countSignals(contentLower, signals);
  const answerTypeBoost = Math.min(answerSignalCount * 0.08, 0.32);

  const mustFindHits = mustFind.filter(term => contentLower.includes(safeLower(term)));
  const mustFindBoost = Math.min(mustFindHits.length * 0.07, 0.28);

  const queryTermHits = queryTerms.filter(t => contentLower.includes(t));
  const lexicalCoverage = queryTerms.length ? Math.min(queryTermHits.length / Math.min(queryTerms.length, 16), 1) : 0;

  const metadataBoost =
    (answerType === "code" && (safeLower(metadata.chunk_type).includes("kode") || contentLower.includes("rincian"))) ? 0.10 :
    (answerType === "procedure" && safeLower(metadata.chunk_type).includes("pedoman")) ? 0.08 :
    0;

  const pageStart = Number(metadata.page_start || 999);
  const positionPenalty = Math.min(pageStart / 500, 0.03);

  const retryScore =
    (semanticScore * 0.48) +
    (keywordScore * 0.16) +
    (lexicalCoverage * 0.14) +
    answerTypeBoost +
    mustFindBoost +
    metadataBoost -
    positionPenalty;

  return {
    content,
    metadata,
    similarity: semanticScore,
    keyword_score: keywordScore,
    keyword_matches: keywordMatches,
    lexical_coverage: lexicalCoverage,
    answer_type_boost: answerTypeBoost,
    answer_signal_count: answerSignalCount,
    must_find_boost: mustFindBoost,
    must_find_hits: mustFindHits,
    metadata_boost: metadataBoost,
    retry_score: retryScore,
    hybrid_score: retryScore
  };
});

rerankedChunks.sort((a, b) => b.retry_score - a.retry_score);
const topChunks = rerankedChunks.slice(0, 6);

console.log("=== RETRY RERANK COMPLETE ===");
console.log("Top retry chunks:", topChunks.map((c, i) => ({
  rank: i + 1,
  score: Number(c.retry_score.toFixed(3)),
  answer_type_boost: c.answer_type_boost,
  must_find_boost: c.must_find_boost,
  doc_id: c.metadata.doc_id,
  page_start: c.metadata.page_start
})));

return [{
  json: {
    ...planner,
    ...retryData,
    chunks: topChunks,
    total_chunks: topChunks.length,
    strategy: "retry_path",
    rerank_method: "answer_type_retry",
    current_query: currentQuery,
    answer_type: answerType,
    retry_attempt: 1
  }
}];

